// Build Gemini API request for image generation
const input = $input.first().json;
const { base64Images, prompt, aspectRatio, temperature } = input;

const parts = [];
if (base64Images.length === 1) {
  parts.push({ inline_data: { mime_type: 'image/jpeg', data: base64Images[0] } });
  parts.push({ text: `REFERENCE JEWELRY IMAGE (above): This is the exact jewelry piece to reproduce.\n\n${prompt}` });
} else {
  parts.push({ text: `REFERENCE JEWELRY IMAGES: The following ${base64Images.length} images show the SAME jewelry piece from different angles. Study ALL of them carefully to capture every detail — shape, metal color, stone cuts, engravings, and proportions.` });
  for (let i = 0; i < base64Images.length; i++) {
    parts.push({ inline_data: { mime_type: 'image/jpeg', data: base64Images[i] } });
    parts.push({ text: `[Reference angle ${i + 1}/${base64Images.length}]` });
  }
  parts.push({ text: `\nUSING ALL ${base64Images.length} REFERENCE IMAGES ABOVE — reproduce this exact jewelry with perfect fidelity:\n\n${prompt}` });
}

return [{
  json: {
    ...input,
    geminiBody: {
      contents: [{ parts }],
      generationConfig: {
        responseModalities: ['TEXT', 'IMAGE'],
        temperature: temperature || 0.12,
        imageConfig: {
          aspectRatio: aspectRatio || '3:4',
          imageSize: '4K'
        }
      }
    },
    attempt: 1,
    maxAttempts: 3,
    temperatures: [temperature || 0.12, (temperature || 0.12) + 0.05, (temperature || 0.12) + 0.10],
    delays: [0, 3000, 5000]
  }
}];

const input = $input.first().json;
const response = input;

// Check if we got a valid image response
try {
  const body = typeof response.body === 'string' ? JSON.parse(response.body) : response.body;
  const candidate = body?.candidates?.[0];

  if (!candidate || candidate.finishReason === 'SAFETY') {
    return [{ json: { ...input, success: false, error: candidate?.finishReason || 'no candidates', attempt: 1 } }];
  }

  // Find image part
  const parts = candidate.content?.parts || [];
  const imagePart = parts.find(p => p.inlineData?.data);

  if (!imagePart) {
    return [{ json: { ...input, success: false, error: 'no image in response', attempt: 1 } }];
  }

  return [{ json: { ...input, success: true, imageBase64: imagePart.inlineData.data, mimeType: imagePart.inlineData.mimeType || 'image/jpeg' } }];
} catch (err) {
  return [{ json: { ...input, success: false, error: err.message, attempt: 1 } }];
}

// Rebuild request with higher temperature for attempt 2
const input = $input.first().json;
const temp2 = (input.temperatures || [0.12, 0.17, 0.22])[1];
const geminiBody = { ...input.geminiBody };
geminiBody.generationConfig = { ...geminiBody.generationConfig, temperature: temp2 };
return [{ json: { ...input, geminiBody, attempt: 2 } }];

