const temp3 = (input.temperatures || [0.12, 0.17, 0.22])[2];
const geminiBody = { ...input.geminiBody };
geminiBody.generationConfig = { ...geminiBody.generationConfig, temperature: temp3 };
return [{ json: { ...input, geminiBody, attempt: 3 } }];

