}

// Upload image to MinIO via S3-compatible API
const input = $input.first().json;
const { imageBase64, userId, jobId, index } = input;

// Convert base64 to buffer
const buffer = Buffer.from(imageBase64, 'base64');
const path = `${userId}/generated_${jobId}_${index}.jpg`;

return [{
  json: {
    ...input,
    uploadPath: path,
    uploadBucket: 'jewelry-images',
    imageBuffer: imageBase64,
    contentType: 'image/jpeg'
  }
}];

// Generate the public URL for the uploaded image
const input = $input.first().json;
const publicEndpoint = '/storage';
const url = `${publicEndpoint}/jewelry-images/${input.uploadPath}`;

return [{
  json: {
    success: true,
    url: url,
    uploadPath: input.uploadPath,
    index: input.index,
    sceneType: input.sceneType || 'unknown'
  }
}];
